public static class AccessibilityMeaningRunner {
 public static void Run(){SessionState.SetBool("MeaningBeforeFix",false);Launch();}
 public static void BeforeFix(){SessionState.SetBool("MeaningBeforeFix",true);Launch();}
 static void Launch(){SessionState.SetBool("MeaningAudit",true);SessionState.SetString("MeaningDir",Path.Combine(Path.GetTempPath(),"DespachoMeaning-"+Guid.NewGuid().ToString("N")));EditorApplication.EnterPlaymode();}
 public static void Restart(){DeskPreferences.TestDirectory=File.ReadAllText("Logs/Accessibility-meaning-directory.txt");DeskPreferences.Load();AccessPreferences.Load();bool ok=AccessPreferences.Current.textScale==1.5f&&AccessPreferences.Current.simpleDocuments&&DeskPreferences.Current.master==.8f;File.WriteAllText("Logs/Accessibility-meaning-restart.txt",ok?"PASS separate process preserves independently scoped general and accessibility preferences":"FAIL semantic restart");EditorApplication.Exit(ok?0:1);}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Before(){if(!SessionState.GetBool("MeaningAudit",false))return;DeskSaveStore.TestDirectory=SessionState.GetString("MeaningDir","");DeskPreferences.TestDirectory=DeskSaveStore.TestDirectory;}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void After(){if(!SessionState.GetBool("MeaningAudit",false))return;SessionState.SetBool("MeaningAudit",false);new GameObject("MeaningAudit").AddComponent<AccessibilityMeaningProbe>();}
}
